<body>

<div class="container">
    <header>
        <h1>Newtonian Motion Lab</h1>
        <p class="subtitle">Interactive exploration of friction and inertia</p>
    </header>

    <main id="content-root">
        <!-- Content will be injected here by the renderer -->
    </main>
</div>

<!-- Formula Lab Modal -->
<div class="modal-overlay" id="formula-lab-modal">
    <div class="modal">
        <button class="modal-close" onclick="closeModal()">&times;</button>
        <h3>Formula Lab: Friction Force</h3>
        <p style="margin-bottom: 16px; color: var(--text-muted); font-size: 0.9rem;">
            Calculate the kinetic friction force opposing the motion.
        </p>
        <div class="formula-display" id="lab-formula-display">
            <!-- Dynamic Formula -->
        </div>
        <div class="variable-input-group">
            <span class="variable-label">μ</span>
            <input type="range" id="lab-mu" min="0" max="1" step="0.01" value="0.1">
            <span id="lab-mu-val">0.10</span>
        </div>
        <div class="variable-input-group">
            <span class="variable-label">N</span>
            <input type="range" id="lab-n" min="10" max="100" step="1" value="50">
            <span id="lab-n-val">50 N</span>
        </div>
        <div style="margin-top: 20px; padding-top: 16px; border-top: 1px solid var(--border);">
            <strong>Result: </strong> <span id="lab-result" style="color: var(--primary); font-weight: bold;">5.00 N</span>
        </div>
    </div>
</div>

<!-- Toast Notification -->
<div class="toast" id="toast">Simulation Started</div>

<script>
    // ==========================================
    // DATA & CONTENT MODEL
    // ==========================================

    const courseContent = [
        {
            type: 'card',
            title: 'Quick Definition',
            content: `
                <p><strong>Kinetic Friction</strong> is the force that opposes the relative motion of solid surfaces sliding against each other. It depends on the materials in contact and the normal force, but <strong>not</strong> on the sliding speed or contact area.</p>
            `
        },
        {
            type: 'simulation',
            title: 'Live Sandbox: Sliding Block',
            id: 'sim-block'
        },
        {
            type: 'formula',
            latex: 'f_k = \\mu_k N',
            title: 'Kinetic Friction Formula',
            variables: { f_k: 'Kinetic Friction Force', mu_k: 'Coefficient of Kinetic Friction', N: 'Normal Force' },
            context: 'This formula calculates the force resisting the motion of the block.'
        },
        {
            type: 'card',
            title: 'Key Concepts',
            content: `
                <ul>
                    <li><strong>Coefficient of Friction (μ):</strong> A dimensionless scalar value. Ice on ice has μ ≈ 0.05, while Rubber on concrete has μ ≈ 1.0.</li>
                    <li><strong>Normal Force (N):</strong> The support force exerted upon an object that is in contact with another stable object. Usually equal to the object's weight on a flat surface.</li>
                    <li><strong>Zero Friction Scenario:</strong> If μ scales to zero, $f_k$ becomes 0. According to Newton's First Law, the object will slide forever at constant velocity unless acted upon by another force.</li>
                </ul>
            `
        },
        {
            type: 'table',
            title: 'Material Properties',
            headers: ['Material Pair', 'Coeff. of Friction (μ)', 'Behavior'],
            rows: [
                ['Teflon on Teflon', '0.04', 'Extremely slippery'],
                ['Ice on Ice', '0.05 - 0.1', 'Low resistance'],
                ['Wood on Wood', '0.25 - 0.5', 'Moderate resistance'],
                ['Rubber on Concrete', '0.6 - 0.85', 'High grip']
            ]
        },
        {
            type: 'card',
            title: 'Summary',
            content: `
                <p>As the coefficient of friction ($\\mu_k$) approaches zero, the friction force ($f_k$) vanishes. In the simulation, you will observe the block maintaining its velocity for much longer distances, eventually stopping only due to numerical precision or air resistance (not modeled here).</p>
            `
        }
    ];

    // ==========================================
    // RENDERING SYSTEM
    // ==========================================

    const root = document.getElementById('content-root');

    function renderContent() {
        courseContent.forEach(section => {
            if (section.type === 'card') {
                root.appendChild(createCard(section));
            } else if (section.type === 'formula') {
                root.appendChild(createFormulaCard(section));
            } else if (section.type === 'simulation') {
                root.appendChild(createSimulationCard(section));
            } else if (section.type === 'table') {
                root.appendChild(createTableCard(section));
            }
        });

        // Render Math
        renderMathInElement(root, {
            delimiters: [
                {left: "$$", right: "$$", display: true},
                {left: "$", right: "$", display: false}
            ],
            throwOnError : false
        });
    }

    function createCard(data) {
        const el = document.createElement('section');
        el.className = 'card';
        el.innerHTML = `
            <div class="card-header">
                <span class="card-title">${data.title}</span>
                <span class="badge">Textbook</span>
            </div>
            <div class="card-body">${data.content}</div>
        `;
        return el;
    }

    function createFormulaCard(data) {
        const el = document.createElement('section');
        el.className = 'card';
        el.innerHTML = `
            <div class="card-header">
                <span class="card-title">
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg>
                    ${data.title}
                </span>
                <span class="badge">Formula</span>
            </div>
            <div class="formula-display">
                $$${data.latex}$$
            </div>
            <div style="font-size: 0.9rem; color: var(--text-muted); margin-bottom: 16px; text-align: center;">
                <em>${data.context}</em>
            </div>
            <div class="formula-actions">
                <button class="btn btn-outline" onclick="explainFormula('${data.title}')">Explain Formula</button>
                <button class="btn" onclick="openFormulaLab('${data.latex}')">Open Formula Lab</button>
            </div>
            <div id="explanation-${data.title.replace(/\s+/g, '-')}" class="hidden" style="margin-top: 16px; padding-top: 16px; border-top: 1px solid var(--border); font-size: 0.9rem;">
                <strong>Variable Breakdown:</strong>
                <ul style="margin-left: 20px; margin-top: 8px;">
                    ${Object.entries(data.variables).map(([key, val]) => `<li><strong>$${key}$</strong>: ${val}</li>`).join('')}
                </ul>
            </div>
        `;
        return el;
    }

    function createTableCard(data) {
        const el = document.createElement('section');
        el.className = 'card';
        const rowsHtml = data.rows.map(row => `<tr>${row.map(cell => `<td>${cell}</td>`).join('')}</tr>`).join('');

        el.innerHTML = `
            <div class="card-header">
                <span class="card-title">${data.title}</span>
                <span class="badge">Reference</span>
            </div>
            <div class="table-wrapper">
                <table>
                    <thead>
                        <tr>${data.headers.map(h => `<th>${h}</th>`).join('')}</tr>
                    </thead>
                    <tbody>
                        ${rowsHtml}
                    </tbody>
                </table>
            </div>
        `;
        return el;
    }

    function createSimulationCard(data) {
        const el = document.createElement('section');
        el.className = 'card';
        el.innerHTML = `
            <div class="card-header">
                <span class="card-title">
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="5 3 19 12 5 21 5 3"/></svg>
                    ${data.title}
                </span>
                <span class="badge" style="background:#dcfce7; color:#166534">Live</span>
            </div>

            <div class="sim-container" id="sim-stage">
                <div class="sim-floor"></div>
                <div class="block" id="sim-block">M</div>
                <div class="vector-arrow" id="vel-vector" style="width: 0px; bottom: 70px;">
                    <span class="vector-label">v</span>
                </div>
            </div>

            <div class="status-bar" id="sim-status">
                <span>⚪ Ready to simulate.</span>
            </div>

            <div class="controls" style="margin-top: 20px;">
                <div class="control-group">
                    <label>
                        Coefficient ($\\mu_k$)
                        <span id="mu-display">0.30</span>
                    </label>
                    <input type="range" id="mu-slider" min="0" max="1.0" step="0.01" value="0.30">
                </div>
                <div class="control-group">
                    <label>
                        Initial Velocity ($v_0$)
                        <span id="v0-display">15 m/s</span>
                    </label>
                    <input type="range" id="v0-slider" min="5" max="30" step="1" value="15">
                </div>
                <div class="control-group" style="justify-content: flex-end;">
                    <button class="btn" id="btn-start">Push Block</button>
                    <button class="btn btn-outline" id="btn-reset">Reset</button>
                </div>
            </div>
        `;

        // Attach Simulation Logic after DOM insertion
        setTimeout(() => initSimulation(), 0);
        return el;
    }

    // ==========================================
    // INTERACTION LOGIC
    // ==========================================

    function explainFormula(titleId) {
        const el = document.getElementById(`explanation-${titleId.replace(/\s+/g, '-')}`);
        el.classList.toggle('hidden');
    }

    // Formula Lab Logic
    let labFormulaLatex = '';

    function openFormulaLab(latex) {
        labFormulaLatex = latex;
        const modal = document.getElementById('formula-lab-modal');
        modal.classList.add('active');

        // Render formula in modal
        const display = document.getElementById('lab-formula-display');
        display.innerHTML = `$$${latex}$$`;
        renderMathInElement(display);

        updateLabCalc();
    }

    function closeModal() {
        document.getElementById('formula-lab-modal').classList.remove('active');
    }

    // Lab Inputs
    document.getElementById('lab-mu').addEventListener('input', (e) => {
        document.getElementById('lab-mu-val').textContent = parseFloat(e.target.value).toFixed(2);
        updateLabCalc();
    });

    document.getElementById('lab-n').addEventListener('input', (e) => {
        document.getElementById('lab-n-val').textContent = e.target.value + ' N';
        updateLabCalc();
    });

    function updateLabCalc() {
        const mu = parseFloat(document.getElementById('lab-mu').value);
        const N = parseFloat(document.getElementById('lab-n').value);
        const fk = mu * N;

        document.getElementById('lab-result').textContent = fk.toFixed(2) + ' N';
    }

    function showToast(msg) {
        const t = document.getElementById('toast');
        t.textContent = msg;
        t.classList.add('show');
        setTimeout(() => t.classList.remove('show'), 3000);
    }

    // ==========================================
    // PHYSICS ENGINE
    // ==========================================

    let simState = {
        running: false,
        x: 50, // pixels
        v: 0,  // m/s (virtual)
        mu: 0.3,
        v0: 15,
        mass: 5, // kg
        scale: 10, // pixels per meter
        dt: 1/60, // seconds per frame
        animId: null
    };

    function initSimulation() {
        const block = document.getElementById('sim-block');
        const sliderMu = document.getElementById('mu-slider');
        const sliderV0 = document.getElementById('v0-slider');
        const btnStart = document.getElementById('btn-start');
        const btnReset = document.getElementById('btn-reset');
        const velVector = document.getElementById('vel-vector');

        // Update UI from sliders
        sliderMu.addEventListener('input', (e) => {
            simState.mu = parseFloat(e.target.value);
            document.getElementById('mu-display').textContent = simState.mu.toFixed(2);
            if (!simState.running) updateStatus(`Friction set to $\\mu = ${simState.mu}$`);
        });

        sliderV0.addEventListener('input', (e) => {
            simState.v0 = parseFloat(e.target.value);
            document.getElementById('v0-display').textContent = simState.v0 + ' m/s';
            if (!simState.running) updateStatus(`Initial velocity set to $v_0 = ${simState.v0}$ m/s`);
        });

        btnStart.addEventListener('click', () => {
            if (simState.running) return;
            startSim();
        });

        btnReset.addEventListener('click', () => {
            stopSim();
            resetSim();
        });

        resetSim();

        function resetSim() {
            simState.x = 50;
            simState.v = 0;
            simState.running = false;
            block.style.transform = `translateX(0px)`;
            velVector.style.width = '0px';
            updateStatus("Ready. Adjust parameters and push block.");
            renderMathInElement(document.getElementById('sim-status'));
        }

        function startSim() {
            simState.running = true;
            simState.v = simState.v0;
            simState.x = 50; // reset pos
            updateStatus("Simulating... Block is decelerating.");
            renderMathInElement(document.getElementById('sim-status'));
            showToast("Simulation Started");
            loop();
        }

        function stopSim() {
            simState.running = false;
            cancelAnimationFrame(simState.animId);
        }

        function loop() {
            if (!simState.running) return;

            // Physics: a = -mu * g
            // g = 9.8
            const g = 9.8;
            const a = -simState.mu * g;

            // Euler integration
            simState.v += a * simState.dt;
            simState.x += simState.v * simState.scale * simState.dt;

            // Stop condition
            if (simState.v <= 0) {
                simState.v = 0;
                simState.running = false;
                updateStatus("Stopped. Velocity reached zero.");
                renderMathInElement(document.getElementById('sim-status'));
                showToast("Block Stopped");
            }

            // Render
            block.style.transform = `translateX(${simState.x - 50}px)`;

            // Visualizing Velocity Vector
            // Scale vector length for visibility
            const vecLen = Math.max(0, simState.v * 5); 
            velVector.style.width = `${vecLen}px`;
            velVector.style.transform = `translateX(${simState.x}px)`;

            // Loop bounds (wrap around for infinite feel if mu is very low)
            if (simState.x > 800) {
                simState.x = 50;
            }

            simState.animId = requestAnimationFrame(loop);
        }
    }

    function updateStatus(text) {
        document.getElementById('sim-status').innerHTML = `<span>${text}</span>`;
    }

    // Initialize App
    document.addEventListener('DOMContentLoaded', renderContent);

</script>
</body>
</html>
